/* Includes ------------------------------------------------------------------*/
#include "example.h"

/* Private typedef -----------------------------------------------------------*/
/* Private define ------------------------------------------------------------*/
/* Private macro -------------------------------------------------------------*/
/** VDDA must be computed not static.
  * @user: The Analog Voltage supply, VDDA, might be different from VDD and might require to be tuned.
  */
#define VDDA_APPLI_MILLIVOLT  3300U

#define DAC_ARRAY_SIZE   3
/* Private variables ---------------------------------------------------------*/
hal_comp_handle_t *pCOMP;  /* pointer referencing the COMP handle from the generated code */
volatile uint8_t CompCallback;
hal_dac_handle_t *pDAC;  /* pointer referencing the DAC handle from the generated code */
/** output voltage values of the DAC.
  * @user: you can change the values to change the output voltage of the DAC.
  */
const uint16_t DacMilliVoltArray[DAC_ARRAY_SIZE] =
{
  VDDA_APPLI_MILLIVOLT / 4,
  VDDA_APPLI_MILLIVOLT / 3,
  VDDA_APPLI_MILLIVOLT / 2
};
uint8_t DacTabIndex = 0;
/* Private functions prototype -----------------------------------------------*/
static void CompCpltCallback(hal_comp_handle_t *CompCallback);

app_status_t app_init(void)
{
  app_status_t return_status = EXEC_STATUS_ERROR;

  /** ########## Step 1 ##########
    * The applicative code initializes the DAC instance.
    */
  pDAC = mx_example_dac_init();

  if (pDAC == NULL)
  {
    goto _app_init_exit;
  }
  /* The calibration allows a better output voltage precision */
  if (HAL_DAC_CalibrateChannelBuffer(pDAC, MX_DAC_CHANNEL) != HAL_OK)
  {
    goto _app_init_exit;
  }

  if (HAL_DAC_StartChannel(pDAC, MX_DAC_CHANNEL) != HAL_OK)
  {
    goto _app_init_exit;
  }


  /** ########## Step 2 ##########
    * The applicative code initializes the COMP instance.
    */
  pCOMP = mx_example_comp_init();

  if (pCOMP == NULL)
  {
    goto _app_init_exit;
  }

  if (HAL_COMP_RegisterOutputTriggerCallback(pCOMP, CompCpltCallback) != HAL_OK)
  {
    goto _app_init_exit;
  }

  /** ########## Step 3 ##########
    * Starts the comparator in interrupt mode.
    */
  if (HAL_COMP_Start_IT(pCOMP) != HAL_OK)
  {
    goto _app_init_exit;
  }

  return_status = EXEC_STATUS_INIT_OK;

_app_init_exit:
  return return_status;
} /* end app_init */


app_status_t app_process(void)
{
  app_status_t return_status = EXEC_STATUS_ERROR;
  CompCallback = 0;

  /** ########## Step 4 ##########
    * The DAC outputs a different voltage at each call. The DAC conversion is done as soon as the value
    * for the output is set.
    */
  /* Configuration of the desired output voltage */
  uint8_t dac_raw_value = LL_DAC_CALC_VOLTAGE_TO_DATA(VDD_VALUE, DacMilliVoltArray[DacTabIndex], LL_DAC_RESOLUTION_8B);
  /* Set value DAC1 */
  if (HAL_DAC_SetChannelData(pDAC, MX_DAC_CHANNEL, dac_raw_value) != HAL_OK)
  {
    goto _app_process_exit;
  }

  if (HAL_DAC_TrigSWConversionChannel(pDAC, MX_DAC_CHANNEL) != HAL_OK)
  {
    goto _app_process_exit;
  }
  /* The DacTabIndex is updated to change the next output voltage value */

  DacTabIndex  = (DacTabIndex + 1) % DAC_ARRAY_SIZE;
  HAL_Delay(100);

  /** ########## Step 5 ##########
    * The application switches to STOP mode.
    */
  /** In debug mode, it is necessary to suspend the Tick increment to prevent WakeUp by Systick interrupt.
     * Otherwise the Systick interrupt wakes the device up within 1ms (HAL time base).
     */
  HAL_SuspendTick();

  /* Enter STOP Mode with WaitForInterrupt parameter, after the system wake-up triggered by the comparator interrupt.*/

  mx_pwr_enter_low_power();

  /** ########## Step 6 ##########
    * The comparator generates an interrupt and system wakes-up from Stop mode. The CompCallback is expected.
    * then the application re-configures the clock.
    */

  if (mx_pwr_system_was_low_power() != 0U)
  {
      /* Restore the systick */
      HAL_ResumeTick();

      /* Reconfigure the system.*/
      mx_pwr_exit_low_power();
  }

  if (CompCallback)
  {
    return_status = EXEC_STATUS_OK;
  }
_app_process_exit:
  return  return_status;
} /* end app_process */


/* De-initializes the COMP instance. */
app_status_t app_deinit(void)
{
  mx_example_comp_deinit();

  return EXEC_STATUS_OK;
} /* end app_deinit */


/** COMP callback
  * @user This implementation of Comparator completion callback can be customized.
  * This function is executed when the Comparator interrupt is generated.
  */
static void CompCpltCallback(hal_comp_handle_t *hComp)
{
  CompCallback = 1U;
}

